/** 把區段拼成完整地圖，並取出所有物件 */
export function parseStage(def) {
  const H = def.height;
  const rows = Array.from({ length: H }, () => '');
  def.segments.forEach((seg, si) => {
    if (seg.length !== H) throw new Error(`${def.id} 區段 ${si}：高度 ${seg.length}，應為 ${H}`);
    const w = seg[0].length;
    seg.forEach((r, y) => { if (r.length !== w) throw new Error(`${def.id} 區段 ${si} 第 ${y} 列：寬 ${r.length}，應為 ${w}`); rows[y] += r; });
  });
  const MW = rows[0].length, MH = H;
  const tiles = new Uint8Array(MW * MH);
  const ents = [];
  const movers = [];
  let spawn = null, gate = null, bells = 0, signs = 0;
  for (let ty = 0; ty < MH; ty++) for (let tx = 0; tx < MW; tx++) {
    const ch = rows[ty][tx];
    if (TILE_CH[ch] != null) { tiles[ty * MW + tx] = TILE_CH[ch]; if (ch === 'D') ents.push({ ch, tx, ty }); continue; }
    if (ch === '.' || ch === '~' || ch === ':') continue;
    if (ch === 'S') { spawn = { tx, ty }; continue; }
    if (ch === 'E') { gate = { tx, ty }; continue; }
    if (ch === 'M') {
      let x1 = tx; while (rows[ty][x1 + 1] === '~') x1++;
      movers.push({ kind: 'h', tx, ty, range: x1 - tx - 1 });
      continue;
    }
    if (ch === 'V') {
      let y1 = ty; while (y1 + 1 < MH && rows[y1 + 1][tx] === ':') y1++;
      movers.push({ kind: 'v', tx, ty, range: y1 - ty });
      continue;
    }
    const e = { ch, tx, ty };
    if (ch === 'B') e.index = bells++;
    if (ch === '?') e.index = signs++;
    ents.push(e);
  }
  if (!spawn) throw new Error(`${def.id}：沒有起點 S`);
  if (!gate) throw new Error(`${def.id}：沒有結界入口 E`);
  const at = (tx, ty) => (tx < 0 || tx >= MW) ? TILE.SOLID : (ty < 0 ? TILE.EMPTY : ty >= MH ? TILE.EMPTY : tiles[ty * MW + tx]);
  return { MW, MH, rows, tiles, ents, movers, spawn, gate, bells, signs, at, set: (tx, ty, v) => { tiles[ty * MW + tx] = v; } };
}
